import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import DashboardCharts from "../components/charts/DashboardCharts";

function AdminDashboard() {

    const navigate = useNavigate();

    const [bookings, setBookings] = useState([]);
    const [dashboardData, setDashboardData] = useState({});
    const [payments, setPayments] = useState([]);
    const [searchText, setSearchText] = useState("");

    useEffect(() => {
        fetchBookings();
        fetchDashboardData();
        fetchPayments();
    }, []);

    // ==========================================
    // FETCH BOOKINGS
    // ==========================================

    const fetchBookings = () => {

        axios
            .get("http://localhost:8081/booking/all")
            .then((response) => {

                if (Array.isArray(response.data)) {
                    setBookings(response.data);
                } else {
                    setBookings([]);
                }

            })
            .catch((error) => {

                console.error(
                    "Booking Error:",
                    error
                );

            });

    };

    // ==========================================
    // FETCH DASHBOARD
    // ==========================================

    const fetchDashboardData = () => {

        axios
            .get("http://localhost:8081/admin/dashboard")
            .then((response) => {

                setDashboardData(
                    response.data || {}
                );

            })
            .catch((error) => {

                console.error(
                    "Dashboard Error:",
                    error
                );

            });

    };

    // ==========================================
    // FETCH PAYMENTS
    // ==========================================

    const fetchPayments = () => {

        axios
            .get("http://localhost:8081/payment/all")
            .then((response) => {

                if (Array.isArray(response.data)) {
                    setPayments(response.data);
                } else {
                    setPayments([]);
                }

            })
            .catch((error) => {

                console.error(
                    "Payment Error:",
                    error
                );

            });

    };

    // ==========================================
    // APPROVE BOOKING
    // ==========================================

    const approveBooking = (id) => {

        axios
            .put(
                `http://localhost:8081/booking/approve/${id}`
            )
            .then(() => {

                alert("Booking Approved");

                fetchBookings();
                fetchDashboardData();

            })
            .catch((error) => {

                console.error(
                    "Approve Error:",
                    error
                );

                alert(
                    "Unable to approve booking."
                );

            });

    };

    // ==========================================
    // REJECT BOOKING
    // ==========================================

    const rejectBooking = (id) => {

        axios
            .put(
                `http://localhost:8081/booking/reject/${id}`
            )
            .then(() => {

                alert("Booking Rejected");

                fetchBookings();
                fetchDashboardData();

            })
            .catch((error) => {

                console.error(
                    "Reject Error:",
                    error
                );

                alert(
                    "Unable to reject booking."
                );

            });

    };

    // ==========================================
    // SEARCH
    // ==========================================

    const filteredBookings = bookings.filter(
        (booking) => {

            const customerName =
                booking.customer &&
                booking.customer.name
                    ? booking.customer.name
                    : "";

            return customerName
                .toLowerCase()
                .includes(
                    searchText.toLowerCase()
                );

        }
    );

    // ==========================================
    // PAGE
    // ==========================================

    return (
        <div
            style={{
                padding: "30px"
            }}
        >

            {/* ==========================================
                TITLE
            ========================================== */}

            <h1>
                Admin Dashboard
            </h1>

            <br />


            {/* ==========================================
                NAVIGATION
            ========================================== */}

            <div
                style={{
                    display: "flex",
                    gap: "15px",
                    marginBottom: "25px"
                }}
            >

                <button
                    onClick={() =>
                        navigate("/manage-cars")
                    }
                    style={{
                        backgroundColor: "black",
                        color: "white",
                        border: "none",
                        padding: "12px 20px",
                        borderRadius: "5px",
                        cursor: "pointer"
                    }}
                >
                    Manage Cars
                </button>


                <button
                    onClick={() =>
                        navigate("/manage-reviews")
                    }
                    style={{
                        backgroundColor: "#ff9800",
                        color: "white",
                        border: "none",
                        padding: "12px 20px",
                        borderRadius: "5px",
                        cursor: "pointer"
                    }}
                >
                    Manage Reviews
                </button>

            </div>


            {/* ==========================================
                SEARCH
            ========================================== */}

            <input
                type="text"
                placeholder="Search By Customer Name"
                value={searchText}
                onChange={(e) =>
                    setSearchText(
                        e.target.value
                    )
                }
                style={{
                    padding: "12px",
                    width: "300px",
                    borderRadius: "5px",
                    border: "1px solid gray"
                }}
            />


            {/* ==========================================
                DASHBOARD CARDS
            ========================================== */}

            <div
                style={{
                    display: "flex",
                    flexWrap: "wrap",
                    gap: "20px",
                    marginTop: "30px",
                    marginBottom: "40px"
                }}
            >

                {/* CUSTOMERS */}

                <div
                    style={{
                        backgroundColor: "#f1f1f1",
                        padding: "20px",
                        width: "220px",
                        borderRadius: "10px"
                    }}
                >

                    <h2>
                        Customers
                    </h2>

                    <h1>
                        {
                            dashboardData.totalCustomers || 0
                        }
                    </h1>

                </div>


                {/* CARS */}

                <div
                    style={{
                        backgroundColor: "#f1f1f1",
                        padding: "20px",
                        width: "220px",
                        borderRadius: "10px"
                    }}
                >

                    <h2>
                        Cars
                    </h2>

                    <h1>
                        {
                            dashboardData.totalCars || 0
                        }
                    </h1>

                </div>


                {/* BOOKINGS */}

                <div
                    style={{
                        backgroundColor: "#f1f1f1",
                        padding: "20px",
                        width: "220px",
                        borderRadius: "10px"
                    }}
                >

                    <h2>
                        Bookings
                    </h2>

                    <h1>
                        {
                            dashboardData.totalBookings || 0
                        }
                    </h1>

                </div>


                {/* PAYMENTS */}

                <div
                    style={{
                        backgroundColor: "#f1f1f1",
                        padding: "20px",
                        width: "220px",
                        borderRadius: "10px"
                    }}
                >

                    <h2>
                        Payments
                    </h2>

                    <h1>
                        {
                            dashboardData.totalPayments ||
                            payments.length
                        }
                    </h1>

                </div>

            </div>


            {/* ==========================================
                CHARTS
            ========================================== */}

            <DashboardCharts
                dashboardData={dashboardData}
            />


            <br />
            <br />


            {/* ==========================================
                BOOKINGS
            ========================================== */}

            <h2>
                Booking Management
            </h2>

            <br />


            {
                filteredBookings.length === 0 ? (

                    <p>
                        No bookings found.
                    </p>

                ) : (

                    filteredBookings.map(
                        (booking) => (

                            <div
                                key={booking.id}
                                style={{
                                    border:
                                        "1px solid lightgray",
                                    padding: "20px",
                                    marginBottom: "20px",
                                    borderRadius: "10px"
                                }}
                            >

                                {/* CAR */}

                                <h2>
                                    {
                                        booking.carVariant &&
                                        booking.carVariant.variantName
                                            ? booking.carVariant.variantName
                                            : "Car"
                                    }
                                </h2>


                                {/* CUSTOMER */}

                                <p>

                                    <b>
                                        Customer:
                                    </b>

                                    {" "}

                                    {
                                        booking.customer &&
                                        booking.customer.name
                                            ? booking.customer.name
                                            : "No Customer"
                                    }

                                </p>


                                {/* EMAIL */}

                                <p>

                                    <b>
                                        Email:
                                    </b>

                                    {" "}

                                    {
                                        booking.customer &&
                                        booking.customer.email
                                            ? booking.customer.email
                                            : "Not Available"
                                    }

                                </p>


                                {/* FROM DATE */}

                                <p>

                                    <b>
                                        From Date:
                                    </b>

                                    {" "}

                                    {
                                        booking.fromDate
                                    }

                                </p>


                                {/* TO DATE */}

                                <p>

                                    <b>
                                        To Date:
                                    </b>

                                    {" "}

                                    {
                                        booking.toDate
                                    }

                                </p>


                                {/* TOTAL */}

                                <p>

                                    <b>
                                        Total Amount:
                                    </b>

                                    {" ₹"}

                                    {
                                        booking.totalAmount || 0
                                    }

                                </p>


                                {/* ASSIGNED CAR */}

                                <p>

                                    <b>
                                        Assigned Car:
                                    </b>

                                    {" "}

                                    {
                                        booking.car &&
                                        booking.car.registrationNumber
                                            ? booking.car.registrationNumber
                                            : "Not Assigned"
                                    }

                                </p>


                                {/* STATUS */}

                                <p>

                                    <b>
                                        Status:
                                    </b>

                                    {" "}

                                    <span
                                        style={{
                                            fontWeight: "bold",
                                            color:
                                                booking.bookingStatus ===
                                                "APPROVED"
                                                    ? "green"
                                                    : booking.bookingStatus ===
                                                      "REJECTED"
                                                    ? "red"
                                                    : "orange"
                                        }}
                                    >

                                        {
                                            booking.bookingStatus ||
                                            "PENDING"
                                        }

                                    </span>

                                </p>


                                {/* BUTTONS */}

                                <div
                                    style={{
                                        marginTop: "15px"
                                    }}
                                >

                                    <button
                                        onClick={() =>
                                            approveBooking(
                                                booking.id
                                            )
                                        }
                                        style={{
                                            backgroundColor: "green",
                                            color: "white",
                                            border: "none",
                                            padding: "10px 15px",
                                            marginRight: "10px",
                                            borderRadius: "5px",
                                            cursor: "pointer"
                                        }}
                                    >
                                        Approve
                                    </button>


                                    <button
                                        onClick={() =>
                                            rejectBooking(
                                                booking.id
                                            )
                                        }
                                        style={{
                                            backgroundColor: "red",
                                            color: "white",
                                            border: "none",
                                            padding: "10px 15px",
                                            borderRadius: "5px",
                                            cursor: "pointer"
                                        }}
                                    >
                                        Reject
                                    </button>

                                </div>

                            </div>

                        )
                    )

                )
            }


            {/* ==========================================
                PAYMENTS
            ========================================== */}

            <br />
            <br />

            <h2>
                Payment Management
            </h2>

            <br />


            {
                payments.length === 0 ? (

                    <p>
                        No payments found.
                    </p>

                ) : (

                    <div>

                        {
                            payments.map(
                                (payment) => (

                                    <div
                                        key={payment.id}
                                        style={{
                                            border:
                                                "1px solid lightgray",
                                            padding: "20px",
                                            marginBottom: "20px",
                                            borderRadius: "10px"
                                        }}
                                    >

                                        <h3>
                                            Payment #
                                            {" "}
                                            {
                                                payment.id
                                            }
                                        </h3>


                                        <p>

                                            <b>
                                                Amount:
                                            </b>

                                            {" ₹"}

                                            {
                                                payment.amount || 0
                                            }

                                        </p>


                                        <p>

                                            <b>
                                                Payment Status:
                                            </b>

                                            {" "}

                                            <span
                                                style={{
                                                    color:
                                                        payment.paymentStatus ===
                                                        "PAID"
                                                            ? "green"
                                                            : "orange",
                                                    fontWeight:
                                                        "bold"
                                                }}
                                            >

                                                {
                                                    payment.paymentStatus ||
                                                    "UNKNOWN"
                                                }

                                            </span>

                                        </p>


                                        <p>

                                            <b>
                                                Payment Date:
                                            </b>

                                            {" "}

                                            {
                                                payment.paymentDate ||
                                                "Not Available"
                                            }

                                        </p>


                                        <p>

                                            <b>
                                                Booking ID:
                                            </b>

                                            {" "}

                                            {
                                                payment.booking &&
                                                payment.booking.id
                                                    ? payment.booking.id
                                                    : "Not Available"
                                            }

                                        </p>


                                        <p>

                                            <b>
                                                Booking Status:
                                            </b>

                                            {" "}

                                            {
                                                payment.booking &&
                                                payment.booking.bookingStatus
                                                    ? payment.booking.bookingStatus
                                                    : "Not Available"
                                            }

                                        </p>


                                        <p>

                                            <b>
                                                Customer:
                                            </b>

                                            {" "}

                                            {
                                                payment.customer &&
                                                payment.customer.name
                                                    ? payment.customer.name
                                                    : payment.booking &&
                                                      payment.booking.customer &&
                                                      payment.booking.customer.name
                                                    ? payment.booking.customer.name
                                                    : "Not Available"
                                            }

                                        </p>


                                    </div>

                                )
                            )
                        }

                    </div>

                )
            }


        </div>
    );

}

export default AdminDashboard;
